@Component("claimReserve-handler")
@ProcessingGroup("claimReserve-processing-group")
public class ClaimReserveEventHandler {
	
	// core constructor
	ClaimReserveEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateClaimReserveEvent
     */
    @EventHandler
    public void handle( CreateClaimReserveEvent event) {
        entityManager.persist(new ClaimReserve(event.getClaimReserveId(), event.getAmount(), event.getSetDate(), event.getClaim(), event.getExposure(), event.getReserveType(), event.getStatus()));
    }

    /*
     * @param	event UpdateClaimReserveEvent
     */
    @EventHandler
    public ClaimReserve handle( UpdateClaimReserveEvent event) {
    	entityManager.merge(new ClaimReserve(event.getClaimReserveId(), event.getAmount(), event.getSetDate(), event.getClaim(), event.getExposure(), event.getReserveType(), event.getStatus()));
    }
    
    /*
     * @param	event DeleteClaimReserveEvent
     */
    @EventHandler
    public void on( DeleteClaimReserveEvent event) {
    	ClaimReserve entity = new ClaimReserve();
   
    	// ------------------------------------------
    	// apply the ClaimReserveId
    	// ------------------------------------------
    	entity.setClaimReserveId( event.getClaimReserveId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final ClaimReserveRepository claimReserveEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(ClaimReserveEventHandler.class.getName());

}
